PortfolioMirrorPage::~PortfolioMirrorPage(){guard([this]{persist();});}
void PortfolioMirrorPage::guard(std::function<void()>fn){if(property("mirrorInitialPending").toBool()){if(status)status->setText("初始资料尚未载入；原草稿未覆盖");return;}try{fn();}catch(const std::exception&e){if(status)status->setText(QString::fromUtf8(e.what()));}}
void PortfolioMirrorPage::loadSavedInstruments(){savedInstrumentPicker->clear();QJsonArray holdings;if(property("mirrorInitialPending").toBool()){need(property("mirrorInitialHoldingsId").toString()==selectedId,"初始镜像原版本不符，未替换");holdings=property("mirrorInitialHoldings").toJsonArray();}else{auto r=store->get(selectedId);auto m=r.value("kind")=="mirror"?r.value("draft").toObject().value("mirror").toObject():r.value("mirror").toObject();holdings=m.value("holdings").toArray();}for(auto v:holdings){auto h=v.toObject();savedInstrumentPicker->addItem(h.value("name").toString()+" / "+h.value("instrumentId").toString(),h.value("instrumentId").toString());}}
void PortfolioMirrorPage::checkEditorCommitted()const{if(selectedRow>=0&&selectedRow<bindings.size()){auto b=bindings[selectedRow].toObject();need(instrumentPicker->currentData().toString()==b.value("instrumentId").toString()&&identityReason->text()==b.value("reason").toString(),"此行身份或依据尚未确认；先点击确认此行完整身份");}}
void PortfolioMirrorPage::refresh(){need(bool(readInputs),"没有只读提供器");input=readInputs();index(input);QString old=accountPicker->currentData().toString();filling=true;accountPicker->clear();for(auto v:input.value("accounts").toArray()){auto a=v.toObject();if(a.value("type")=="ledger")accountPicker->addItem(a.value("name").toString()+" / "+a.value("id").toString(),a.value("id").toString());}int i=accountPicker->findData(old);if(i>=0)accountPicker->setCurrentIndex(i);history->clear();for(auto v:store->catalog()){auto r=v.toObject();auto row=new QListWidgetItem(r.value("savedAt").toString()+" / "+r.value("kind").toString()+" / "+r.value("accountId").toString(),history);row->setData(Qt::UserRole,r.value("id").toString());}filling=false;}
void PortfolioMirrorPage::previewImport(const QByteArray&bytes){auto next=decode(bytes);pending=next;pendingCatalog=store->catalogFingerprint();prepared={};filling=true;snapshotPicker->clear();if(pending.value("kind")=="source")for(auto v:pending.value("snapshots").toArray()){auto s=v.toObject();snapshotPicker->addItem(QString::number(s.value("snapshotIndex").toInt())+" / "+s.value("snapshotAsOf").toString()+" / "+s.value("sourceLabel").toString());}filling=false;accountAck->setChecked(false);if(pending.value("kind")=="source"){chooseSnapshot(0);views->setCurrentIndex(0);status->setText("仅预览；每行绑定完整身份、核对账户后预览差异，再明确保存");}else{showOriginal(pending.value("rawUtf8").toString());status->setText("本机镜像备份仅预览，未覆盖已有版本；确认后原子导入");}persist();}
void PortfolioMirrorPage::chooseSnapshot(int selected){need(pending.value("kind")=="source"&&selected>=0&&selected<pending.value("snapshots").toArray().size(),"没有源快照");bool restoring=filling;selectedSnapshot=selected;prepared={};bindings={};auto m=pending.value("snapshots").toArray()[selected].toObject();filling=true;snapshotPicker->setCurrentIndex(selected);snapshotAsOf->setText(m.value("snapshotAsOf").toString());sourceLabel->setText(m.value("sourceLabel").toString());if(!restoring){accountAck->setChecked(false);accountReason->clear();completeAck->setChecked(false);completenessReason->clear();}rows->clear();for(auto v:m.value("holdings").toArray()){auto r=v.toObject();bindings.append(QJsonObject{{"instrumentId",r.value("instrumentId")},{"reason",""}});rows->addItem(r.value("code").toString()+" "+r.value("name").toString()+" · 数量"+showValue(r.value("quantity"))+" · 成本"+showValue(r.value("costValue"))+" · "+(r.value("instrumentId").toString().isEmpty()?"待明确身份":r.value("instrumentId").toString()));}filling=restoring;selectedRow=-1;instrumentPicker->clear();if(!bindings.isEmpty()){rows->setCurrentRow(0);chooseRow(0);}if(!restoring)persist();}
void PortfolioMirrorPage::chooseRow(int i){need(i>=0&&i<bindings.size(),"先选择源持仓行");selectedRow=i;auto r=pending.value("snapshots").toArray()[selectedSnapshot].toObject().value("holdings").toArray()[i].toObject();instrumentPicker->clear();instrumentPicker->addItem("请选择明确完整证券身份","");for(auto v:input.value("instruments").toArray()){auto ins=v.toObject();QString id=ins.value("id").toString();if(fullId(id)&&id.section(':',2,2)==r.value("code").toString())instrumentPicker->addItem(ins.value("name").toString()+" / "+id,id);}auto b=bindings[i].toObject();int position=instrumentPicker->findData(b.value("instrumentId").toString());if(position>=0)instrumentPicker->setCurrentIndex(position);identityReason->setText(b.value("reason").toString());rowInfo->setText("源代码 "+r.value("code").toString()+" / 市场提示 "+r.value("marketHint").toString()+" / 类型提示 "+r.value("typeHint").toString()+" / 原价 "+showValue(r.value("currentPrice"))+"；数字0保留，未知不填0。");}
void PortfolioMirrorPage::bindRow(){need(selectedRow>=0&&selectedRow<bindings.size()&&!instrumentPicker->currentData().toString().isEmpty(),"需选择明确完整证券身份");bindings[selectedRow]=QJsonObject{{"instrumentId",instrumentPicker->currentData().toString()},{"reason",identityReason->text()}};rows->item(selectedRow)->setText(rows->item(selectedRow)->text().section(" · ",0,2)+" · "+instrumentPicker->currentData().toString());prepared={};persist();}
QJsonObject PortfolioMirrorPage::options()const{return {{"snapshotAsOf",snapshotAsOf->text().trimmed()},{"sourceLabel",sourceLabel->text().trimmed()},{"accountBindingReason",accountReason->text()},{"accountAcknowledged",accountAck->isChecked()},{"completeAcknowledged",completeAck->isChecked()},{"completenessReason",completenessReason->text()}};}
void PortfolioMirrorPage::previewDifference(){checkEditorCommitted();need(pending.value("kind")=="source","先导入持仓源文件");auto fresh=readInputs();prepared=prepare(pending,selectedSnapshot,fresh,accountPicker->currentData().toString(),bindings,options());pendingCatalog=store->catalogFingerprint();displayDifference(prepared.value("reconciliation").toObject());persist();}
void PortfolioMirrorPage::displayDifference(QJsonObject r){QString text="只读对账 · "+r.value("scope").toString()+"\n源时点 "+r.value("mirrorAsOf").toString()+" / 账本时点 "+r.value("ledgerAsOf").toString()+"\n现金 源:"+showValue(r.value("mirrorCash"))+" / 账本:"+showValue(r.value("ledgerCash"))+" / 可比差值:"+showValue(r.value("cashDelta"))+"\n";for(auto v:r.value("rows").toArray()){auto row=v.toObject();text+=row.value("instrumentId").toString()+" · 数量 源"+showValue(row.value("mirrorQuantity"))+" /账本"+showValue(row.value("ledgerQuantity"))+" /差"+showValue(row.value("quantityDelta"))+" · 成本 源"+showValue(row.value("mirrorCost"))+" /账本"+showValue(row.value("ledgerCost"))+" /差"+showValue(row.value("costDelta"))+" · "+row.value("status").toString()+"\n";}text+="\n缺数、不同现金时点和动态收益归因不自动推断。以下为完整冻结证据：\n"+QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented));showOriginal(text);}
void PortfolioMirrorPage::confirmImport(){need(!pending.isEmpty(),"没有待确认预览");if(pending.value("kind")=="backup"){auto records=pending.value("original").toObject().value("records").toArray();QJsonArray ordered;for(auto kind:{"mirror","comparison"})for(auto v:records)if(v.toObject().value("kind")==kind)ordered.append(v);need(ordered.size()==records.size(),"备份有未知记录类别");store->append(ordered,pendingCatalog);}else{checkEditorCommitted();need(!prepared.isEmpty(),"先明确绑定并预览差异");auto ids=QJsonArray{};for(auto v:bindings)ids.append(v.toObject().value("instrumentId"));auto fresh=scope(readInputs(),accountPicker->currentData().toString(),ids);need(bindingContext(fresh)==bindingContext(prepared.value("scope").toObject()),"账户/证券/账本已变化，请重新预览差异");auto record=version(prepared,QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));store->append(QJsonArray{record},pendingCatalog);selectedId=record.value("id").toString();loadSavedInstruments();}pending={};prepared={};bindings={};pendingCatalog.clear();refresh();views->setCurrentIndex(1);persist();status->setText("独立镜像版本已保存；未改账本、现金或行情");}
void PortfolioMirrorPage::cancelImport(){pending={};prepared={};bindings={};pendingCatalog.clear();rows->clear();readText.clear();readOffset=0;reader->clear();views->setCurrentIndex(0);guard([this]{persist();});status->setText("预览已取消");}
void PortfolioMirrorPage::showOriginal(QString text){readText=text;readOffset=0;renderReader();views->setCurrentIndex(2);}
void PortfolioMirrorPage::renderReader(){int start=readOffset,end=std::min(start+24000,int(readText.size()));if(start>0&&readText[start].isLowSurrogate())start--;if(end>0&&end<readText.size()&&readText[end-1].isHighSurrogate())end--;reader->setPlainText(readText.mid(start,end-start));status->setText(QString("完整文本分段 %1–%2 / %3；全量导出不截断").arg(start).arg(end).arg(readText.size()));}
void PortfolioMirrorPage::locate(){need(!selectedId.isEmpty()&&bool(openInstrument),"先选保存版本");auto r=store->get(selectedId);auto m=r.value("kind")=="mirror"?r.value("draft").toObject().value("mirror").toObject():r.value("mirror").toObject();auto hs=m.value("holdings").toArray();need(!hs.isEmpty(),"空镜像没有证券");if(savedInstrumentPicker->count()==0)loadSavedInstruments();QString id=savedInstrumentPicker->currentData().toString();bool bound=false;for(auto v:hs)bound=bound||v.toObject().value("instrumentId")==id;need(bound,"所选完整身份不属于此镜像版本");auto current=index(readInputs()).value("instruments").toObject().value(id).toObject();need(fullId(id)&&!current.isEmpty()&&current.value("id")==id,"完整证券身份不可定位，未按代码改绑");persist();openInstrument(current);}
bool PortfolioMirrorPage::back(){if(views->currentIndex()==2){views->setCurrentIndex(pending.isEmpty()?1:0);guard([this]{persist();});return true;}if(views->currentIndex()==1){views->setCurrentIndex(0);return true;}guard([this]{persist();});return false;}
